import{failure as a,propagateFailure as i,success as s}from"./types.js";const h=t=>r=>{if(!Array.isArray(r))return a("not an array");if(r.length<t.length)return a(`the data has ${r.length} elements but ${t.length} are required`);const u=[];for(let e=0;e<t.length;e++){const l=t[e],o=r[e],n=l(o);if(n.tag==="failure")return i(n,{tag:"array",index:e});u.push(n.value)}return s(u)};export{h as tuple};
